import sys

if len(sys.argv) != 4:
	print('Hata: 3 argüman gerekir (operatör ve iki sayı). Örnek: ./hesap.py + 2 3')
	sys.exit(1)

opr = sys.argv[1]
a = sys.argv[2]
b = sys.argv[3]

if opr not in ['+', '-', '*', '/']:
	print(f'Hata: Geçersiz operatör. Geçerli operatörler: +, -, *, /.')
	sys.exit(1)

try:
	a = float(a)
	b = float(b)
except ValueError:
	print('Hata: Argümanlar sayı olmalıdır.')
	sys.exit(1)

if opr == '+':
	print(f'{a} + {b} = {a + b}')
elif opr == '-':
	print(f'{a} - {b} = {a - b}')
elif opr == '*':
	print(f'{a} * {b} = {a * b}')
elif opr == '/':
	if b == 0:
		print('Hata: Sıfıra bölünme.')
	else:
		print(f'{a} / {b} = {a / b}')

